'use client'

import React from 'react'

interface WeatherData {
  location: string
  current: {
    temperature: number
    condition: string
    humidity: number
    windSpeed: number
    icon: string
  }
  forecast: Array<{
    date: string
    high: number
    low: number
    condition: string
    icon: string
  }>
}

interface WeatherCardProps {
  data: WeatherData
}

const weatherIcons: { [key: string]: string } = {
  sunny: '☀️',
  cloudy: '☁️',
  rainy: '🌧️',
  stormy: '⛈️',
  snowy: '❄️',
  partly_cloudy: '⛅',
  foggy: '🌫️',
  windy: '💨',
  clear: '🌙',
}

export default function WeatherCard({ data }: WeatherCardProps) {
  const getWeatherIcon = (iconName: string) => {
    return weatherIcons[iconName.toLowerCase()] || '🌤️'
  }

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })
  }

  return (
    <div className="bg-gradient-to-br from-blue-400 to-blue-600 dark:from-blue-600 dark:to-blue-800 rounded-xl p-6 text-white shadow-lg">
      <div className="mb-6">
        <h2 className="text-2xl font-bold mb-2">{data.location}</h2>
        <div className="flex items-center justify-between">
          <div>
            <div className="text-5xl font-bold">{Math.round(data.current.temperature)}°</div>
            <div className="text-lg opacity-90">{data.current.condition}</div>
          </div>
          <div className="text-6xl">{getWeatherIcon(data.current.icon)}</div>
        </div>
        <div className="mt-4 flex gap-4 text-sm opacity-80">
          <div>💧 {data.current.humidity}%</div>
          <div>💨 {data.current.windSpeed} mph</div>
        </div>
      </div>

      <div className="border-t border-white/20 pt-4">
        <h3 className="text-lg font-semibold mb-3">5-Day Forecast</h3>
        <div className="grid grid-cols-5 gap-2">
          {data.forecast.map((day, index) => (
            <div key={index} className="text-center">
              <div className="text-xs opacity-80">{formatDate(day.date)}</div>
              <div className="text-2xl my-1">{getWeatherIcon(day.icon)}</div>
              <div className="text-sm">
                <span className="font-semibold">{Math.round(day.high)}°</span>
                <span className="opacity-70"> {Math.round(day.low)}°</span>
              </div>
              <div className="text-xs opacity-70">{day.condition}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
} 