'use client'

import React, { useState, useEffect, useRef } from 'react'
import Sidebar from './components/Sidebar'
import ThemeToggle from './components/ThemeToggle'
import Message from './components/Message'

interface ChatMessage {
  role: 'user' | 'assistant'
  content: string
  components?: Array<{
    type: string
    data: any
  }>
}

interface Chat {
  id: string
  title: string
  messages: ChatMessage[]
  createdAt: string
  updatedAt: string
}

export default function Home() {
  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [chats, setChats] = useState<Chat[]>([])
  const [currentChatId, setCurrentChatId] = useState<string | null>(null)
  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [input, setInput] = useState('')
  const [isStreaming, setIsStreaming] = useState(false)
  const [streamingContent, setStreamingContent] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)

  // Load chats from backend on mount
  useEffect(() => {
    fetchChats()
  }, [])

  // Scroll to bottom when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages, streamingContent])

  const fetchChats = async () => {
    try {
      const response = await fetch('http://localhost:8000/api/chats')
      if (response.ok) {
        const data = await response.json()
        setChats(data)
      }
    } catch (error) {
      console.error('Failed to fetch chats:', error)
    }
  }

  const handleNewChat = () => {
    setCurrentChatId(null)
    setMessages([])
    setInput('')
  }

  const handleSelectChat = async (chatId: string) => {
    try {
      const response = await fetch(`http://localhost:8000/api/chats/${chatId}`)
      if (response.ok) {
        const chat = await response.json()
        setCurrentChatId(chat.id)
        setMessages(chat.messages)
      }
    } catch (error) {
      console.error('Failed to fetch chat:', error)
    }
  }

  const handleDeleteChat = async (chatId: string) => {
    try {
      const response = await fetch(`http://localhost:8000/api/chats/${chatId}`, {
        method: 'DELETE'
      })
      if (response.ok) {
        setChats(chats.filter(chat => chat.id !== chatId))
        if (currentChatId === chatId) {
          handleNewChat()
        }
      }
    } catch (error) {
      console.error('Failed to delete chat:', error)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!input.trim() || isStreaming) return

    const userMessage: ChatMessage = { role: 'user', content: input }
    const newMessages = [...messages, userMessage]
    setMessages(newMessages)
    setInput('')
    setIsStreaming(true)
    setStreamingContent('')

    try {
      const response = await fetch('http://localhost:8000/api/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages: newMessages,
          chatId: currentChatId
        })
      })

      if (!response.ok) throw new Error('Failed to send message')

      const reader = response.body?.getReader()
      const decoder = new TextDecoder()
      let accumulatedContent = ''
      let components: any[] = []

      while (reader) {
        const { done, value } = await reader.read()
        if (done) break

        const chunk = decoder.decode(value)
        const lines = chunk.split('\n')

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6))
              
              if (data.type === 'content') {
                accumulatedContent += data.data
                setStreamingContent(accumulatedContent)
              } else if (data.type === 'complete') {
                components = data.data.components || []
              } else if (data.type === 'done') {
                const assistantMessage: ChatMessage = {
                  role: 'assistant',
                  content: accumulatedContent,
                  components: components
                }
                const updatedMessages = [...newMessages, assistantMessage]
                setMessages(updatedMessages)
                setStreamingContent('')
                
                // Save or update chat
                if (currentChatId) {
                  await fetch(`http://localhost:8000/api/chats/${currentChatId}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ messages: updatedMessages })
                  })
                } else {
                  const createResponse = await fetch('http://localhost:8000/api/chats', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ messages: updatedMessages })
                  })
                  if (createResponse.ok) {
                    const newChat = await createResponse.json()
                    setCurrentChatId(newChat.id)
                    setChats([...chats, newChat])
                  }
                }
              }
            } catch (error) {
              console.error('Failed to parse SSE data:', error)
            }
          }
        }
      }
    } catch (error) {
      console.error('Failed to send message:', error)
      setStreamingContent('')
    } finally {
      setIsStreaming(false)
    }
  }

  return (
    <div className="flex h-screen bg-white dark:bg-gray-950">
      <Sidebar
        isOpen={sidebarOpen}
        onToggle={() => setSidebarOpen(!sidebarOpen)}
        chats={chats}
        currentChatId={currentChatId}
        onSelectChat={handleSelectChat}
        onNewChat={handleNewChat}
        onDeleteChat={handleDeleteChat}
      />

      <div className={`flex-1 flex flex-col transition-all duration-300 ${
        sidebarOpen ? 'ml-64' : 'ml-0'
      }`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-800">
          <h1 className="text-xl font-semibold text-gray-900 dark:text-white">
            AI Assistant
          </h1>
          <ThemeToggle />
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4">
          {messages.length === 0 && !isStreaming && (
            <div className="text-center text-gray-500 dark:text-gray-400 mt-8">
              <p className="text-lg mb-2">Welcome! How can I help you today?</p>
              <p className="text-sm">Ask me about weather, stock prices, or anything else!</p>
            </div>
          )}
          
          {messages.map((message, index) => (
            <Message
              key={index}
              role={message.role}
              content={message.content}
              components={message.components}
            />
          ))}
          
          {isStreaming && streamingContent && (
            <Message
              role="assistant"
              content={streamingContent}
              isStreaming={true}
            />
          )}
          
          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <form onSubmit={handleSubmit} className="p-4 border-t border-gray-200 dark:border-gray-800">
          <div className="flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your message..."
              className="flex-1 px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
              disabled={isStreaming}
            />
            <button
              type="submit"
              disabled={isStreaming || !input.trim()}
              className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {isStreaming ? (
                <svg className="w-5 h-5 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
              ) : (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}
