'use client'

import React from 'react'

interface StockData {
  symbol: string
  companyName: string
  currentPrice: number
  change: number
  changePercent: number
  historicalData: Array<{
    date: string
    price: number
    volume: number
  }>
}

interface StockCardProps {
  data: StockData
}

export default function StockCard({ data }: StockCardProps) {
  const isPositive = data.change >= 0
  const maxPrice = Math.max(...data.historicalData.map(d => d.price))
  const minPrice = Math.min(...data.historicalData.map(d => d.price))
  const priceRange = maxPrice - minPrice

  const formatDate = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  }

  const formatVolume = (volume: number) => {
    if (volume >= 1000000) {
      return `${(volume / 1000000).toFixed(1)}M`
    } else if (volume >= 1000) {
      return `${(volume / 1000).toFixed(1)}K`
    }
    return volume.toString()
  }

  // Calculate chart points
  const chartWidth = 400
  const chartHeight = 150
  const chartPadding = 10
  const points = data.historicalData.map((item, index) => {
    const x = (index / (data.historicalData.length - 1)) * (chartWidth - 2 * chartPadding) + chartPadding
    const y = chartHeight - ((item.price - minPrice) / priceRange) * (chartHeight - 2 * chartPadding) - chartPadding
    return { x, y, data: item }
  })

  const pathData = points.map((point, index) => 
    `${index === 0 ? 'M' : 'L'} ${point.x} ${point.y}`
  ).join(' ')

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-lg">
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-2xl font-bold text-gray-900 dark:text-white">{data.symbol}</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400">{data.companyName}</p>
        </div>
        <div className="text-right">
          <div className="text-2xl font-bold text-gray-900 dark:text-white">
            ${data.currentPrice.toFixed(2)}
          </div>
          <div className={`text-sm font-medium ${isPositive ? 'text-green-600' : 'text-red-600'}`}>
            {isPositive ? '+' : ''}{data.change.toFixed(2)} ({isPositive ? '+' : ''}{data.changePercent.toFixed(2)}%)
          </div>
        </div>
      </div>

      <div className="mb-4">
        <svg width="100%" height={chartHeight} viewBox={`0 0 ${chartWidth} ${chartHeight}`} className="overflow-visible">
          {/* Grid lines */}
          {[0, 0.25, 0.5, 0.75, 1].map((ratio) => {
            const y = chartPadding + ratio * (chartHeight - 2 * chartPadding)
            return (
              <line
                key={ratio}
                x1={chartPadding}
                y1={y}
                x2={chartWidth - chartPadding}
                y2={y}
                stroke="currentColor"
                strokeOpacity="0.1"
                className="text-gray-400"
              />
            )
          })}
          
          {/* Chart line */}
          <path
            d={pathData}
            fill="none"
            stroke={isPositive ? '#10b981' : '#ef4444'}
            strokeWidth="2"
          />
          
          {/* Data points */}
          {points.map((point, index) => (
            <g key={index}>
              <circle
                cx={point.x}
                cy={point.y}
                r="3"
                fill={isPositive ? '#10b981' : '#ef4444'}
                className="cursor-pointer hover:r-5"
              />
              <title>
                {formatDate(point.data.date)}: ${point.data.price.toFixed(2)}
              </title>
            </g>
          ))}
        </svg>
      </div>

      <div className="border-t border-gray-200 dark:border-gray-700 pt-4">
        <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">10-Day History</h4>
        <div className="grid grid-cols-5 gap-2 text-xs">
          {data.historicalData.slice(-5).map((item, index) => (
            <div key={index} className="text-center">
              <div className="text-gray-600 dark:text-gray-400">{formatDate(item.date)}</div>
              <div className="font-medium text-gray-900 dark:text-white">${item.price.toFixed(2)}</div>
              <div className="text-gray-500 dark:text-gray-500">Vol: {formatVolume(item.volume)}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
} 